/* The record editor lives in RecordEditor.tsx so its form behavior is isolated from dashboard navigation and data loading.
function EntitySelect({name,value,set,rows}:{name:"mine_id"|"monitoring_area_id";value:unknown;set:(name:string,value:unknown)=>void;rows:Row[]}) { return <select required value={String(value??"")} onChange={event=>set(name,event.target.value)} className="field mt-1 w-full"><option value="">Selecione</option>{rows.map(row=><option key={row.id} value={row.id}>{String(row.name??"Sem nome")} · ID {row.id}</option>)}</select>; }
function Editor({row,resource,save,close,mines,areas}:{row?:Row;resource:string;save:(x:Record<string,unknown>)=>Promise<void>;close:()=>void;mines:Row[];areas:Row[]}) {
 const fields=forms[resource]??[];const [data,setData]=useState<Record<string,unknown>>(()=>Object.fromEntries(fields.map(f=>[f.name,row?.[f.name]??(f.kind==="boolean"?true:"")])));
 const [e,setE]=useState("");const [busy,setBusy]=useState(false);
 const set=(name:string,value:unknown)=>setData(x=>({...x,[name]:value}));
 const point=typeof data.longitude==="number"&&typeof data.latitude==="number"?[data.longitude,data.latitude] as Position:typeof data.longitude==="string"&&typeof data.latitude==="string"&&data.longitude!==""&&data.latitude!==""?[Number(data.longitude),Number(data.latitude)] as Position:undefined;
 const geometry=data.geometry as Geometry|undefined;const polygon=geometry?.type==="Polygon"?(geometry.coordinates as Position[][])[0]??[]:[];
 async function submit(event:FormEvent){event.preventDefault();try{const body:Record<string,unknown>={...data};delete body.location;for(const f of fields){if(f.kind==="number"&&body[f.name]!=="")body[f.name]=Number(body[f.name]);if(f.kind==="datetime"&&body[f.name])body[f.name]=new Date(String(body[f.name])).toISOString();if(f.kind==="map-area"){const pts=(body.geometry as Geometry|undefined)?.coordinates as Position[][]|undefined;if(!pts?.[0]||pts[0].length<3)throw Error("Marque ao menos três vértices no mapa para definir a área.");const ring=[...pts[0]];if(ring[0][0]!==ring.at(-1)?.[0]||ring[0][1]!==ring.at(-1)?.[1])ring.push([...ring[0]]);body.geometry={type:"Polygon",coordinates:[ring]};}if(body[f.name]===""&&f.kind!=="boolean")delete body[f.name];}setBusy(true);await save(body);close();}catch(c){setE(err(c));}finally{setBusy(false);}}
 return <form onSubmit={submit} className="grid gap-4 sm:grid-cols-2">{fields.length?fields.map(f=>f.kind==="map-point"?<div key={f.name} className="sm:col-span-2"><p className="mb-1 text-sm text-slate-300">Localização no mapa</p><OperationalMap mode="point" point={point} onPointChange={([longitude,latitude])=>{set("longitude",longitude);set("latitude",latitude);}}/></div>:f.kind==="map-area"?<div key={f.name} className="sm:col-span-2"><div className="mb-1 flex items-center justify-between text-sm text-slate-300"><span>{resource==="mines"?"Delimite a área da mina no mapa":"Delimitação da jazida no mapa"}</span><button type="button" onClick={()=>set("geometry",undefined)} className="text-amber-300">Limpar área</button></div><OperationalMap mode="polygon" polygon={polygon} onPolygonChange={points=>set("geometry",{type:"Polygon",coordinates:[points]})}/>{resource==="mines"&&<p className="mt-2 text-xs text-slate-400">O ponto de referência da mina será calculado a partir deste polígono.</p>}</div>:<label key={f.name} className={"text-sm text-slate-300 "+(f.kind==="textarea"||f.kind==="vertices"?"sm:col-span-2":"")}>{label(f.name)}{f.name==="mine_id"?<EntitySelect name="mine_id" value={data[f.name]} set={set} rows={mines}/>:f.name==="monitoring_area_id"?<EntitySelect name="monitoring_area_id" value={data[f.name]} set={set} rows={areas}/>:f.kind==="boolean"?<input type="checkbox" checked={Boolean(data[f.name])} onChange={x=>set(f.name,x.target.checked)} className="ml-3 accent-amber-400"/>:f.kind==="textarea"||f.kind==="vertices"?<textarea required={["name","geometry","notes"].includes(f.name)&&!row} value={String(data[f.name]??"")} placeholder={f.kind==="vertices"?"longitude,latitude; longitude,latitude; longitude,latitude":""} onChange={x=>set(f.name,x.target.value)} className="field mt-1 h-24 w-full"/>:f.kind==="select"?<select required value={String(data[f.name]??"")} onChange={x=>set(f.name,x.target.value)} className="field mt-1 w-full"><option value="">Selecione</option>{f.choices?.map(x=><option key={x} value={x}>{choiceLabels[x]??x}</option>)}</select>:<input required={["name","email","role","status","latitude","longitude","inspector_user_id"].includes(f.name)&&!row} type={f.kind==="date"?"date":f.kind==="datetime"?"datetime-local":f.kind==="number"?"number":f.name==="password"?"password":"text"} value={String(data[f.name]??"")} onChange={x=>set(f.name,x.target.value)} className="field mt-1 w-full"/>}</label>):<p className="sm:col-span-2 text-slate-400">Este recurso é criado pelos fluxos operacionais e não possui cadastro manual.</p>}{e&&<p className="sm:col-span-2 text-red-200">{e}</p>}<button disabled={busy||!fields.length} className="w-fit rounded-xl bg-amber-400 px-4 py-2 font-semibold text-slate-950 disabled:opacity-60">{busy?"Salvando…":"Salvar"}</button></form>;
} */

export default function Dashboard(){
 const router=useRouter(); const [view,setView]=useState<View>("overview"),[resource,setResource]=useState("mines"),[rows,setRows]=useState<Row[]>([]),[summary,setSummary]=useState<Record<string,unknown>|null>(null),[map,setMap]=useState<MapLayers|null>(null),[me,setMe]=useState<Row|null>(null),[loading,setLoading]=useState(true),[error,setError]=useState(""),[notice,setNotice]=useState(""),[editing,setEditing]=useState<Row|"new"|null>(null),[editorResource,setEditorResource]=useState<string|null>(null),[revision,setRevision]=useState(0),[preview,setPreview]=useState<string|null>(null),[search,setSearch]=useState(""),[area,setArea]=useState(""),[file,setFile]=useState<File|null>(null),[inspection,setInspection]=useState(""),[mines,setMines]=useState<Row[]>([]),[areas,setAreas]=useState<Row[]>([]);
 const [imagePagination,setImagePagination]=useState({key:"",page:1});
 const [imageMeta,setImageMeta]=useState<List["meta"]>({page:1,per_page:20,total:0,last_page:1});
 const listRequest=useRef(0);
 const request=useCallback(async<T,>(fn:()=>Promise<T>)=>{setError("");try{return await fn();}catch(e){setError(err(e));return undefined;}},[]);
 const target=view==="alerts"?"alerts":view==="images"?"satellite-images":view==="analysis"?"analysis-jobs":view==="inspections"?"inspections":view==="reports"?"reports":resource;
 const paginatedImages=target==="satellite-images"||target==="inspection-images";
 const imageKey=`${target}:${search}`;
 const imagePage=imagePagination.key===imageKey?imagePagination.page:1;
 const load=useCallback(async(name=target)=>{const current=++listRequest.current;const paginate=name==="satellite-images"||name==="inspection-images";const page=paginate&&name===target?imagePage:1;setLoading(true);setError("");try{const r=await api<List>(`/${name}?per_page=${paginate?20:100}&page=${page}&search=${encodeURIComponent(search)}`);if(current!==listRequest.current)return;setRows(r.data);if(paginate)setImageMeta(r.meta);}catch(e){if(current===listRequest.current)setError(err(e));}finally{if(current===listRequest.current)setLoading(false);}},[target,search,imagePage]);
 useEffect(()=>{if(!sessionStorage.getItem("minevision.access_token")){router.replace("/");return;}void request(()=>api<Row>("/auth/me")).then(x=>x&&setMe(x));},[router,request]);
 useEffect(()=>{if(!sessionStorage.getItem("minevision.access_token"))return;void Promise.all([api<List>("/mines?per_page=100"),api<List>("/monitoring-areas?per_page=100")]).then(([mineList,areaList])=>{setMines(mineList.data);setAreas(areaList.data);}).catch(()=>undefined);},[]);
 useEffect(()=>{if(view==="overview"){setLoading(true);void request(()=>api<Record<string,unknown>>("/dashboard/summary")).then(x=>{if(x)setSummary(x);setLoading(false);});}else if(view==="map"){setLoading(true);void request(()=>api<MapLayers>("/map/features")).then(x=>{if(x)setMap(x);setLoading(false);});}else if(!["account","regulation","exploration","intelligence"].includes(view))void load();else setLoading(false);},[view,resource,load,request]);
 const activeEditorResource=editorResource??target;
 async function save(body:Record<string,unknown>){const r=editing!=="new"&&editing?await request(()=>api<Row>(`/${activeEditorResource}/${editing.id}`,{method:"PATCH",body:JSON.stringify(body)})):await request(()=>api<Row>(`/${activeEditorResource}`,{method:"POST",body:JSON.stringify(body)}));if(r){setNotice("Registro salvo.");setRevision(x=>x+1);if(!editorResource)void load();}}
 async function del(row:Row){if(!confirm(`Excluir #${row.id}?`))return;const r=await request(()=>api(`/${target}/${row.id}`,{method:"DELETE"}));if(r){setNotice("Registro excluído.");void load();}}
 async function image(id:number){const b=await request(()=>apiBlob(`/satellite-images/${id}/preview`));if(b)setPreview(URL.createObjectURL(b));}
 function openReport(token:unknown){if(typeof token!=="string"||!/^[a-f0-9]{64}$/.test(token)){setError("Este relatório ainda não possui um link web. Atualize a lista e tente novamente.");return;}window.open(`/reports/${token}`,"_blank","noopener");}
 async function downloadReport(id:number){const pdf=await request(()=>apiBlob(`/reports/${id}/pdf`));if(!pdf)return;const url=URL.createObjectURL(pdf),link=document.createElement("a");link.href=url;link.download=`relatorio-minevision-${id}.pdf`;link.click();URL.revokeObjectURL(url);}
 async function acquire(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=new FormData(e.currentTarget);const sources=["SENTINEL-1","SENTINEL-2"].filter(source=>form.get(source)==="on");const r=await request(()=>api<Row[]>(`/monitoring-areas/${area}/satellite-images`,{method:"POST",body:JSON.stringify({start:String(form.get("start")),end:String(form.get("end")),sources})}));if(r){setNotice(`${r.length} imagens adquiridas.`);void load("satellite-images");}}
 async function analyze(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);const body={...Object.fromEntries(["mine_id","monitoring_area_id","reference_image_id","current_image_id","threshold"].map(k=>[k,Number(f.get(k))])),analysis_type:String(f.get("analysis_type")??"CHANGE_DETECTION")};const r=await request(()=>api("/change-detections/analyze",{method:"POST",body:JSON.stringify(body)}));if(r){setNotice("Análise enfileirada.");setView("analysis");}}
 async function report(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);const r=await request(()=>api<Row>("/reports",{method:"POST",body:JSON.stringify({mine_id:Number(f.get("mine_id")),title:f.get("title"),type:f.get("type"),period_start:f.get("period_start"),period_end:f.get("period_end")})}));if(r){setNotice("Relatório gerado.");openReport(r.public_token);setView("reports");}}
 async function upload(e:FormEvent){e.preventDefault();if(!file||!inspection)return;const bytes=new Uint8Array(await file.arrayBuffer());const content_base64=btoa(Array.from(bytes,x=>String.fromCharCode(x)).join(""));const r=await request(()=>api(`/inspections/${inspection}/images`,{method:"POST",body:JSON.stringify({content_base64,description:file.name})}));if(r)setNotice("Foto enviada.");
 }
 async function logout(){await request(()=>api("/auth/logout",{method:"POST"}));sessionStorage.clear();router.replace("/");}
 const cols=useMemo(()=>Array.from(new Set(rows.flatMap(x=>Object.keys(x).filter(k=>!["geometry","metadata_json","content_json","result_json","public_token","description","notes"].includes(k))))).slice(0,7),[rows]);
 const actionDelete=!["satellite-images","spectral-indices","change-detections","analysis-jobs","inspection-images","companies"].includes(target);
  return <main className="app-shell"><aside className="app-sidebar"><a className="brand" href="/" aria-label="MineVision, página inicial"><span className="brand-mark" aria-hidden="true">M</span><span>Mine<span className="brand-accent">Vision</span></span></a><p className="sidebar-label">ESPAÇO DE TRABALHO</p><nav className="app-nav" aria-label="Navegação do sistema">{nav.map(([id,t])=><button key={id} onClick={()=>setView(id)} className={view===id?"active":""} aria-current={view===id?"page":undefined}><span className="app-nav-icon" aria-hidden="true">{navIcons[id]}</span>{t}</button>)}</nav><p className="sidebar-bottom">MineVision · Ambiente demonstrativo<br/>Dados para apresentação do sistema</p></aside><section className="app-main"><header className="app-header"><div><p className="app-header-label">MINEVISION / {nav.find(x=>x[0]===view)?.[1].toUpperCase()}</p><h1>Olá, {String(me?.name??"equipe").split(" ")[0]}</h1></div><div className="app-header-right"><span className="app-avatar" aria-hidden="true">{String(me?.name??"MV").slice(0,2).toUpperCase()}</span><button onClick={logout} className="app-logout">Sair da conta</button></div></header><div className="app-content">{error&&<p role="alert" className="mb-5 rounded border border-red-200 bg-red-50 p-4 text-red-800">{error}</p>}{notice&&<p role="status" className="mb-5 rounded border border-green-200 bg-green-50 p-4 text-green-800">{notice}</p>}
 {view==="overview"&&<Overview summary={summary} loading={loading} go={setView}/>}
 {view==="map"&&<Map map={map} loading={loading}/>}
 {view==="exploration"&&<MineralExploration areas={areas}/>}
 {view==="regulation"&&<Regulation areas={areas} revision={revision} create={name=>{setEditorResource(name);setEditing("new");}} edit={(name,row)=>{setEditorResource(name);setEditing(row);}}/>}
 {view==="intelligence"&&<Intelligence areas={areas}/>}
 {view==="account"&&<Account me={me}/>}
  {view==="resources"&&<div className="app-toolbar"><label className="text-sm font-bold text-green-900">Tipo de cadastro <select value={resource} onChange={e=>setResource(e.target.value)} className="field ml-3">{options.map(([v,t])=><option value={v} key={v}>{t}</option>)}</select></label><button onClick={()=>setEditing("new")} className="app-button">+ Novo registro</button></div>}
  {["resources","images","analysis","alerts","inspections","reports"].includes(view)&&<><Special view={view} acquire={acquire} analyze={analyze} report={report} upload={upload} area={area} setArea={setArea} inspection={inspection} setInspection={setInspection} setFile={setFile} mines={mines} areas={areas}/><div className="app-toolbar"><div><p className="app-kicker">REGISTROS DA OPERAÇÃO</p><h2>{options.find(x=>x[0]===target)?.[1]}</h2></div><div className="app-toolbar-actions"><input className="field w-44" aria-label="Buscar registros" placeholder="Buscar registros" value={search} onChange={e=>{setSearch(e.target.value);setImagePagination({key:"",page:1});}}/><button onClick={()=>void load()} className="app-button app-button-secondary">Atualizar</button>{["alerts","inspections"].includes(view)&&<button onClick={()=>setEditing("new")} className="app-button">+ Novo</button>}</div></div><Table rows={rows} cols={cols} loading={loading} target={target} edit={setEditing} del={del} preview={image} openReport={openReport} deletable={actionDelete} mines={mines} areas={areas}/>{paginatedImages&&!loading&&<nav className="app-pagination" aria-label="Paginação das imagens"><span>{imageMeta.total?`${(imageMeta.page-1)*imageMeta.per_page+1}–${Math.min(imageMeta.page*imageMeta.per_page,imageMeta.total)} de ${imageMeta.total} imagens`:"Nenhuma imagem"}</span><div><button type="button" className="app-button app-button-secondary" disabled={imagePage<=1} onClick={()=>setImagePagination({key:imageKey,page:imagePage-1})}>Anterior</button><span aria-live="polite">Página {imageMeta.page} de {imageMeta.last_page}</span><button type="button" className="app-button app-button-secondary" disabled={imagePage>=imageMeta.last_page} onClick={()=>setImagePagination({key:imageKey,page:imagePage+1})}>Próxima</button></div></nav>}</>}
  </div></section>{editing&&<Modal title={editing==="new"?"Novo registro":`Editar #${editing.id}`} close={()=>{setEditing(null);setEditorResource(null);}}><RecordEditor resource={activeEditorResource} row={editing==="new"?undefined:editing} save={save} close={()=>{setEditing(null);setEditorResource(null);}} mines={mines} areas={areas}/></Modal>}{preview&&<Modal title="Prévia de satélite" close={()=>{URL.revokeObjectURL(preview);setPreview(null);}}><img src={preview} alt="Imagem de satélite" className="w-full rounded-xl"/></Modal>}</main>;
}
function Overview({summary,loading,go}:{summary:Record<string,unknown>|null;loading:boolean;go:(v:View)=>void}){const c=summary?.counts as Record<string,number>|undefined;const cards:[string,unknown,View][]=[["Minas cadastradas",c?.mines,"resources"],["Hectares monitorados",c?.monitored_hectares,"map"],["Alertas abertos",c?.open_alerts,"alerts"],["Inspeções pendentes",c?.pending_inspections,"inspections"]];const alerts=(summary?.recent_alerts??[]) as Row[];return <><div className="app-page-intro"><p className="app-kicker">VISÃO GERAL / OPERAÇÃO</p><h2>O território em perspectiva.</h2><p>Acompanhe os principais dados do ambiente demonstrativo.</p></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{cards.map(([t,v,x])=><button onClick={()=>go(x)} key={t} className="app-stat"><span className="app-stat-label">{t}</span><strong className="app-stat-value">{loading?"…":typeof v==="number"?new Intl.NumberFormat("pt-BR",{maximumFractionDigits:1}).format(v):val(v)}</strong><span className="app-stat-arrow" aria-hidden="true">↗</span></button>)}</div><div className="mt-6 grid gap-5 xl:grid-cols-[1.5fr_1fr]"><section className="app-panel p-6"><div className="flex items-center justify-between"><div><p className="app-kicker">ACOMPANHAMENTO</p><h3 className="mt-2 font-serif text-2xl">Alertas recentes</h3></div><button className="text-sm font-bold text-green-800" onClick={()=>go("alerts")}>Ver todos →</button></div>{alerts.length?alerts.map(a=><div key={a.id} className="mt-4 flex items-center justify-between gap-3 border-b border-green-100 pb-4 text-sm"><span>{val(a.title)}</span><Tag value={a.severity}/></div>):<p className="app-empty">Nenhum alerta recente neste ambiente.</p>}</section><section className="app-panel p-6"><p className="app-kicker">FLUXO DE TRABALHO</p><h3 className="mt-2 font-serif text-2xl">Próximos passos</h3><p className="mt-3 text-sm leading-6 text-green-900/70">Explore as áreas no mapa, consulte imagens e acompanhe as ocorrências registradas.</p><div className="mt-7 grid gap-2"><button className="app-button text-left" onClick={()=>go("map")}>Abrir mapa operacional ↗</button><button className="app-button app-button-secondary text-left" onClick={()=>go("images")}>Consultar imagens →</button></div></section></div></>;}
function Regulation({areas,revision,create,edit}:{areas:Row[];revision:number;create:(resource:string)=>void;edit:(resource:string,row:Row)=>void}){const [area,setArea]=useState("");const [layers,setLayers]=useState<Row[]>([]);const [assets,setAssets]=useState<Row[]>([]);const [rules,setRules]=useState<Row[]>([]);const [context,setContext]=useState<Record<string,unknown>|null>(null);const [sync,setSync]=useState<Record<string,unknown>|null>(null);const [busy,setBusy]=useState(false);const [failure,setFailure]=useState("");const [refresh,setRefresh]=useState(0);useEffect(()=>{let active=true;void Promise.all([api<List>("/compliance-layers?per_page=100"),api<List>("/operational-assets?per_page=100"),api<List>("/notification-rules?per_page=100")]).then(([layerList,assetList,ruleList])=>{if(active){setLayers(layerList.data);setAssets(assetList.data.filter(asset=>["LICENSE","TAILINGS_DAM"].includes(String(asset.kind))));setRules(ruleList.data);}}).catch(error=>active&&setFailure(err(error)));return()=>{active=false;};},[revision,refresh]);async function inspect(action:"context"|"sync"){if(!area)return;setBusy(true);setFailure("");try{if(action==="sync"){setSync(await api<Record<string,unknown>>(`/monitoring-areas/${area}/official-layers/sync`,{method:"POST"}));setRefresh(value=>value+1);}setContext(await api<Record<string,unknown>>(`/monitoring-areas/${area}/risk-context`));}catch(error){setFailure(err(error));}finally{setBusy(false);}}const matches=(context?.matches??[]) as Row[];return <div className="max-w-6xl"><div className="app-page-intro"><p className="app-kicker">GOVERNANÇA E CONFORMIDADE</p><h2>Regulamentação em um único lugar.</h2><p>Gerencie camadas oficiais, licenças, estruturas, regras de acompanhamento e o cruzamento territorial da operação.</p></div><section className="app-panel mt-6 p-6"><div className="flex flex-wrap items-center justify-between gap-4"><div><p className="app-kicker">ANÁLISE TERRITORIAL</p><h3 className="mt-1 font-serif text-2xl">Contexto e fontes oficiais</h3></div><button className="app-button app-button-secondary" onClick={()=>create("compliance-layers")}>+ Nova camada</button></div><div className="mt-5 flex flex-wrap gap-3"><select value={area} onChange={event=>setArea(event.target.value)} className="field min-w-72"><option value="">Selecione uma área monitorada</option>{areas.map(item=><option value={item.id} key={item.id}>{String(item.name)} · ID {item.id}</option>)}</select><button disabled={!area||busy} onClick={()=>void inspect("context")} className="app-button">{busy?"Consultando…":"Analisar contexto"}</button><button disabled={!area||busy} onClick={()=>void inspect("sync")} className="app-button app-button-secondary">Atualizar fontes oficiais</button></div>{failure&&<p className="mt-4 text-red-700">{failure}</p>}{sync&&<p className="mt-4 rounded border border-green-200 bg-green-50 p-4 text-sm text-green-800">Fontes atualizadas: {val(sync.imported)} importada(s) e {val(sync.updated)} atualizada(s).</p>}{context&&<><div className="mt-6 flex items-center gap-3"><Tag value={context.priority}/><strong>Índice de prioridade: {val(context.risk_score)}</strong></div><p className="mt-4 rounded border border-amber-200 bg-amber-50 p-4 text-sm text-amber-950">{val(context.notice)}</p>{matches.length?<div className="app-table mt-4"><table><thead><tr><th>Camada</th><th>Fonte</th><th>Referência</th><th>Sobreposição</th><th>Prioridade</th></tr></thead><tbody>{matches.map(match=><tr key={match.id}><td>{val(match.name)}</td><td>{val(match.source)}</td><td>{match.source_url?<a className="text-green-800 underline" href={String(match.source_url)} target="_blank" rel="noreferrer">{val(match.external_id)||"Abrir fonte"}</a>:val(match.external_id)}</td><td>{val(match.overlap_hectares)} ha</td><td><Tag value={match.priority}/></td></tr>)}</tbody></table></div>:<p className="app-empty mt-4">Nenhuma sobreposição nas camadas cadastradas.</p>}</>}</section><div className="mt-5 grid gap-5 xl:grid-cols-3"><RegulationList title="Camadas regulatórias" description="Restrições, direitos minerários e áreas protegidas." rows={layers} columns={["name","source","category","legal_status"]} create={()=>create("compliance-layers")} edit={row=>edit("compliance-layers",row)}/><RegulationList title="Licenças e estruturas" description="Licenças e barragens vinculadas à operação." rows={assets} columns={["name","kind","status","due_at"]} create={()=>create("operational-assets")} edit={row=>edit("operational-assets",row)}/><RegulationList title="Regras de acompanhamento" description="Critérios para governar notificações e revisões." rows={rules} columns={["name","event_type","minimum_severity","active"]} create={()=>create("notification-rules")} edit={row=>edit("notification-rules",row)}/></div><p className="mt-5 text-xs text-slate-500">Os cruzamentos e cadastros apoiam a priorização operacional e exigem confirmação de vigência, enquadramento e avaliação técnica/jurídica.</p></div>}
function RegulationList({title,description,rows,columns,create,edit}:{title:string;description:string;rows:Row[];columns:string[];create:()=>void;edit:(row:Row)=>void}){return <section className="app-panel p-5"><div className="flex items-start justify-between gap-3"><div><h3 className="font-serif text-xl">{title}</h3><p className="mt-2 text-sm text-green-900/70">{description}</p></div><button onClick={create} className="app-button app-button-secondary whitespace-nowrap">+ Novo</button></div>{rows.length?<div className="app-table mt-4"><table><thead><tr>{columns.map(column=><th key={column}>{label(column)}</th>)}<th>Ações</th></tr></thead><tbody>{rows.slice(0,5).map(row=><tr key={row.id}>{columns.map(column=><td key={column}>{column==="minimum_severity"?<Tag value={row[column]}/>:column==="active"?String(row[column]===true?"Ativa":"Inativa"):column.endsWith("_at")?when(row[column]):val(row[column])}</td>)}<td><button className="text-green-800" onClick={()=>edit(row)}>Editar</button></td></tr>)}</tbody></table></div>:<p className="app-empty mt-4">Nenhum registro cadastrado.</p>}{rows.length>5&&<p className="mt-3 text-xs text-slate-500">Exibindo 5 de {rows.length} registros.</p>}</section>}
function MineralExploration({areas}:{areas:Row[]}){const [area,setArea]=useState("");const [result,setResult]=useState<Record<string,any>|null>(null);const [rows,setRows]=useState<Row[]>([]);const [busy,setBusy]=useState(false);const [failure,setFailure]=useState("");async function sync(){if(!area)return;setBusy(true);setFailure("");try{const response=await api<Record<string,any>>(`/monitoring-areas/${area}/mineral-exploration/sync`,{method:"POST"});setResult(response);const records=await api<List>(`/mineral-occurrences?monitoring_area_id=${area}&per_page=100`);setRows(records.data);}catch(e){setFailure(err(e));}finally{setBusy(false);}}return <div className="max-w-5xl"><div className="app-page-intro"><p className="app-kicker">EXPLORAÇÃO MINERAL / OURO</p><h2>Cruze evidências, não promessas.</h2><p>Ocorrências públicas do GeoSGB/SGB são combinadas com os indicadores espectrais Sentinel-2 já processados para apoiar a triagem geológica.</p></div><section className="app-panel mt-6 p-6"><div className="flex flex-wrap gap-3"><select value={area} onChange={e=>setArea(e.target.value)} className="field min-w-72"><option value="">Selecione uma área monitorada</option>{areas.map(a=><option key={a.id} value={a.id}>{String(a.name)} · ID {a.id}</option>)}</select><button className="app-button" disabled={!area||busy} onClick={()=>void sync()}>{busy?"Consultando GeoSGB…":"Atualizar ocorrências oficiais"}</button></div>{failure&&<p className="mt-4 text-red-700">{failure}</p>}{result&&<><div className="mt-6 grid gap-4 sm:grid-cols-3"><div><p className="app-kicker">IMPORTADAS</p><strong className="text-2xl">{Number(result.imported??0)+Number(result.updated??0)}</strong></div><div><p className="app-kicker">ALVOS ESPECTRAIS</p><strong className="text-2xl">{val(result.spectral_crossing?.gold_potential_detections)}</strong></div><div><p className="app-kicker">CONFIANÇA MÁX.</p><strong className="text-2xl">{val(result.spectral_crossing?.highest_confidence)}%</strong></div></div><p className="mt-5 rounded border border-amber-200 bg-amber-50 p-4 text-sm text-amber-950">{val(result.spectral_crossing?.interpretation)}</p><p className="mt-3 text-xs text-slate-500">{val(result.disclaimer)}</p></>}</section><section className="app-panel mt-5 p-6"><h3 className="font-serif text-2xl">Ocorrências de ouro na área</h3>{rows.length?<div className="app-table mt-4"><table><thead><tr><th>Ocorrência</th><th>Tipo</th><th>Status econômico</th><th>Importância</th><th>Fonte</th></tr></thead><tbody>{rows.map(row=><tr key={row.id}><td>{val(row.name)}</td><td>{val(row.occurrence_type)}</td><td>{val(row.economic_status)}</td><td>{val(row.importance)}</td><td><a className="text-green-800 underline" href={String(row.source_url)} target="_blank" rel="noreferrer">SGB/GeoSGB</a></td></tr>)}</tbody></table></div>:<p className="app-empty mt-4">Atualize uma área para consultar as ocorrências públicas de ouro do GeoSGB.</p>}</section></div>}
function Intelligence({areas}:{areas:Row[]}){const [area,setArea]=useState("");const [score,setScore]=useState<Record<string,unknown>|null>(null);const [question,setQuestion]=useState("");const [answer,setAnswer]=useState<Record<string,unknown>|null>(null);const [busy,setBusy]=useState(false);const [failure,setFailure]=useState("");async function assess(){if(!area)return;setBusy(true);setFailure("");try{setScore(await api(`/monitoring-areas/${area}/opportunity-score`));}catch(e){setFailure(err(e));}finally{setBusy(false);}}async function ask(e:FormEvent){e.preventDefault();setBusy(true);setFailure("");try{setAnswer(await api("/copilot/query",{method:"POST",body:JSON.stringify({question,monitoring_area_id:area?Number(area):undefined})}));}catch(e){setFailure(err(e));}finally{setBusy(false);}}const components=(score?.components??[]) as Row[];return <div className="max-w-4xl"><div className="app-page-intro"><p className="app-kicker">INTELIGÊNCIA EXPLICÁVEL</p><h2>Priorize alvos com evidências.</h2><p>Score transparente que combina assinaturas espectrais, cobertura Sentinel e contexto regulatório.</p></div><section className="app-panel mt-6 p-6"><div className="flex flex-wrap gap-3"><select value={area} onChange={e=>setArea(e.target.value)} className="field min-w-72"><option value="">Selecione uma área monitorada</option>{areas.map(a=><option key={a.id} value={a.id}>{String(a.name)} · ID {a.id}</option>)}</select><button className="app-button" disabled={!area||busy} onClick={()=>void assess()}>{busy?"Calculando…":"Calcular score"}</button></div>{failure&&<p className="mt-4 text-red-700">{failure}</p>}{score&&<><div className="mt-6 flex gap-3"><Tag value={score.recommendation}/><strong>Score: {val(score.opportunity_score)}/100</strong></div><div className="app-table mt-4"><table><thead><tr><th>Componente</th><th>Pontos</th><th>Evidência</th></tr></thead><tbody>{components.map(c=><tr key={String(c.name)}><td>{val(c.name)}</td><td>{val(c.points)}</td><td>{val(c.evidence)}</td></tr>)}</tbody></table></div><p className="mt-4 text-xs text-slate-500">{val(score.disclaimer)}</p></>}</section><section className="app-panel mt-5 p-6"><p className="app-kicker">COPILOTO</p><h3 className="font-serif text-2xl">Pergunte sobre a operação</h3><form onSubmit={ask} className="mt-4 flex flex-wrap gap-3"><input required value={question} onChange={e=>setQuestion(e.target.value)} className="field min-w-72 flex-1" placeholder="Ex.: quais alertas exigem atenção?"/><button className="app-button" disabled={busy}>Consultar evidências</button></form>{answer&&<><p className="mt-5 leading-7">{val(answer.answer)}</p><p className="mt-3 text-xs text-slate-500">{val(answer.limitations)}</p></>}</section></div>}
function Map({map,loading}:{map:MapLayers|null;loading:boolean}){
  const [selected,setSelected]=useState<GeoFeature|null>(null);
  const [selectedLayer,setSelectedLayer]=useState<{name:string;description:string;count:number}|null>(null);
  const [expanded,setExpanded]=useState(false);
  useEffect(()=>{if(!expanded)return;const close=(event:KeyboardEvent)=>{if(event.key==="Escape")setExpanded(false);};document.addEventListener("keydown",close);return()=>document.removeEventListener("keydown",close);},[expanded]);
  // Preserva a referência das feições ao abrir o painel de detalhes. Assim o
  // mapa não interpreta a seleção como um novo conjunto de dados e não muda o zoom.
  const features=useMemo(()=>Object.entries(map??{}).flatMap(([resource,layer])=>layer.features.map(feature=>({...feature,properties:{...feature.properties,resource:String(feature.properties.resource??resource)}}))),[map]);
  const name=(feature:GeoFeature)=>String(feature.properties.name??feature.properties.title??`${label(String(feature.properties.resource))} #${feature.id}`);const details=selected;
  const mapView=<OperationalMap features={features as MapFeature[]} fullScreen={expanded} onFeatureSelect={feature=>{setSelectedLayer(null);setSelected(feature as GeoFeature);}} onLayerSelect={layer=>{setSelected(null);setSelectedLayer(layer);}}/>;
  const information=details?<><p className="text-xs uppercase tracking-widest text-amber-400">{label(String(details.properties.resource))}</p><h3 className="mt-2 font-semibold">{name(details)}</h3><p className="mt-3 text-sm text-slate-400">ID #{details.id}</p>{["description","status","severity","municipality","state","mineral","notes","legal_status"].filter(key=>details.properties[key]).map(key=><p key={key} className="mt-2 text-sm"><span className="text-slate-400">{label(key)}:</span> {val(details.properties[key])}</p>)}<button onClick={()=>setSelected(null)} className="mt-5 text-sm text-amber-300">Limpar seleção</button></>:selectedLayer?<><p className="text-xs uppercase tracking-widest text-amber-400">Camada</p><h3 className="mt-2 font-semibold">{selectedLayer.name}</h3><p className="mt-3 text-sm text-slate-400">{selectedLayer.description}</p><p className="mt-3 text-sm">{selectedLayer.count} elemento{selectedLayer.count===1?"":"s"} nesta camada.</p></>:<><h3 className="font-semibold">Camadas disponíveis</h3><p className="mt-2 text-sm text-slate-400">{features.length} elemento{features.length===1?"":"s"} no mapa. Clique em uma camada para ver sua descrição ou em um elemento para ver os seus dados.</p></>;
  return <><h2 className="text-3xl font-semibold">Mapa operacional</h2><p className="mt-2 text-slate-400">Use o mapa base para visualizar minas, áreas, detecções, alertas e inspeções.</p><div className="mt-4 flex justify-end"><button type="button" onClick={()=>setExpanded(true)} className="app-button app-button-secondary">Expandir mapa ⛶</button></div><div className="mt-3 grid gap-4 xl:grid-cols-[1fr_18rem]">{loading?<div className="rounded-2xl border border-slate-800 p-8">Carregando mapa…</div>:mapView}<aside className="rounded-2xl border border-slate-800 bg-slate-900/50 p-5">{information}</aside></div>{expanded&&<div className="map-fullscreen-shell" role="dialog" aria-modal="true" aria-label="Mapa em tela cheia"><button type="button" className="map-fullscreen-close" onClick={()=>setExpanded(false)}>Fechar mapa ✕</button>{mapView}<aside className="map-fullscreen-details">{information}</aside></div>}</>;
 /* O renderizador SVG legado abaixo foi preservado como referência, mas não é alcançável. */
 if(false){
 const colors:Record<string,string>={mines:"#38bdf8",monitoring_areas:"#fbbf24",change_detections:"#a78bfa",alerts:"#fb7185",inspections:"#34d399"};
 const [visible,setVisible]=useState<Record<string,boolean>>({});const [selected,setSelected]=useState<GeoFeature|null>(null);
 const layers=map?Object.entries(map):[];const features=layers.flatMap(([name,layer])=>layer.features.map(feature=>({...feature,properties:{...feature.properties,resource:String(feature.properties.resource??name)}})));
 const shown=features.filter(feature=>visible[feature.properties.resource??""]!==false);
 const positions=shown.flatMap(feature=>geometryPositions(feature.geometry));
 const bounds=positions.length?positions.reduce((b,[x,y])=>({minX:Math.min(b.minX,x),maxX:Math.max(b.maxX,x),minY:Math.min(b.minY,y),maxY:Math.max(b.maxY,y)}),{minX:positions[0][0],maxX:positions[0][0],minY:positions[0][1],maxY:positions[0][1]}):{minX:-60,maxX:-40,minY:-20,maxY:5};
 const padX=Math.max((bounds.maxX-bounds.minX)*.12,.015),padY=Math.max((bounds.maxY-bounds.minY)*.12,.015);const project=([x,y]:Position):Position=>[48+(x-bounds.minX+padX)/(bounds.maxX-bounds.minX+padX*2)*904,512-(y-bounds.minY+padY)/(bounds.maxY-bounds.minY+padY*2)*944];
 const name=(feature:GeoFeature)=>String(feature.properties.name??feature.properties.title??`${label(String(feature.properties.resource))} #${feature.id}`);
 return <><h2 className="text-3xl font-semibold">Mapa operacional</h2><p className="mt-2 text-slate-400">Visualize as geometrias GeoJSON e selecione um elemento para consultar seus dados.</p>
 <div className="mt-6 grid gap-4 xl:grid-cols-[1fr_18rem]">{loading?<div className="rounded-2xl border border-slate-800 p-8">Carregando mapa…</div>:<div className="overflow-hidden rounded-2xl border border-slate-700 bg-slate-900"><div className="flex flex-wrap gap-x-5 gap-y-2 border-b border-slate-700 bg-slate-900/90 p-4">{layers.map(([key,layer])=><label key={key} className="flex cursor-pointer items-center gap-2 text-sm text-slate-200"><input type="checkbox" checked={visible[key]!==false} onChange={e=>setVisible(x=>({...x,[key]:e.target.checked}))} className="accent-amber-400"/><span className="h-2.5 w-2.5 rounded-full" style={{backgroundColor:colors[key]??"#94a3b8"}}/>{label(key)} <span className="text-slate-500">{layer.features.length}</span></label>)}</div><div className="relative aspect-[16/9] min-h-[340px] bg-[#0b1728]">{shown.length?<svg viewBox="0 0 1000 560" className="h-full w-full" role="img" aria-label="Mapa das áreas monitoradas"><defs><pattern id="grid" width="60" height="60" patternUnits="userSpaceOnUse"><path d="M 60 0 L 0 0 0 60" fill="none" stroke="#334155" strokeWidth="1"/></pattern></defs><rect width="1000" height="560" fill="url(#grid)"/>{shown.map(feature=>{const resource=String(feature.properties.resource);const color=colors[resource]??"#94a3b8";const active=selected?.id===feature.id&&selected.properties.resource===resource;if(feature.geometry.type==="Point"){const [x,y]=project(feature.geometry.coordinates as Position);return <g key={`${resource}-${feature.id}`} onClick={()=>setSelected(feature)} className="cursor-pointer"><circle cx={x} cy={y} r={active?15:11} fill={color} fillOpacity=".95" stroke="white" strokeWidth={active?3:2}/><circle cx={x} cy={y} r="3" fill="#0f172a"/></g>;}return <path key={`${resource}-${feature.id}`} d={geometryPath(feature.geometry,project)} fill={color} fillOpacity={active ? .55 : .28} stroke={color} strokeWidth={active?4:2} className="cursor-pointer" onClick={()=>setSelected(feature)}/>;})}<text x="32" y="42" fill="#cbd5e1" fontSize="16">N</text><path d="M36 50 l-8 18 h16z" fill="#cbd5e1"/></svg>:<div className="grid h-full place-items-center p-8 text-center text-slate-400">Não há geometrias nas camadas selecionadas.</div>}</div></div>}
 <aside className="rounded-2xl border border-slate-800 bg-slate-900/50 p-5">{selected?<><p className="text-xs uppercase tracking-widest text-amber-400">{label(String(selected.properties.resource))}</p><h3 className="mt-2 font-semibold">{name(selected)}</h3><p className="mt-3 text-sm text-slate-400">ID #{selected.id}</p>{["status","severity","municipality","state","mineral"].filter(key=>selected.properties[key]).map(key=><p key={key} className="mt-2 text-sm"><span className="text-slate-400">{label(key)}:</span> {val(selected.properties[key])}</p>)}<button onClick={()=>setSelected(null)} className="mt-5 text-sm text-amber-300">Limpar seleção</button></>:<><h3 className="font-semibold">Camadas ativas</h3><p className="mt-2 text-sm text-slate-400">{shown.length} elemento{shown.length===1?"":"s"} visível{shown.length===1?"":"is"}. Clique no mapa para ver os detalhes.</p></>}</aside></div></>;
}
}
function geometryPositions(geometry:Geometry):Position[]{if(geometry.type==="Point")return [geometry.coordinates as Position];if(geometry.type==="Polygon")return (geometry.coordinates as Position[][]).flat();return (geometry.coordinates as Position[][][]).flat(2);}
function geometryPath(geometry:Geometry,project:(position:Position)=>Position):string{const polygons=geometry.type==="Polygon"?[geometry.coordinates as Position[][]]:geometry.coordinates as Position[][][];return polygons.flatMap(polygon=>polygon.map(ring=>ring.map((position,index)=>{const [x,y]=project(position);return `${index?"L":"M"}${x.toFixed(1)} ${y.toFixed(1)}`;}).join(" ")+" Z")).join(" ");}
function Special({view,acquire,analyze,report,upload,area,setArea,inspection,setInspection,setFile,mines,areas}:{view:View;acquire:(e:FormEvent<HTMLFormElement>)=>void;analyze:(e:FormEvent<HTMLFormElement>)=>void;report:(e:FormEvent<HTMLFormElement>)=>void;upload:(e:FormEvent)=>void;area:string;setArea:(x:string)=>void;inspection:string;setInspection:(x:string)=>void;setFile:(f:File|null)=>void;mines:Row[];areas:Row[]}){const input=(n:string,p:string,type="number")=><input required name={n} placeholder={p} type={type} step={n==="threshold"?"0.01":"1"} className="field"/>;const select=(name:string,items:Row[],placeholder:string,value?:string,onChange?:(value:string)=>void)=><select required name={name} value={value} onChange={event=>onChange?.(event.target.value)} className="field"><option value="">{placeholder}</option>{items.map(item=><option key={item.id} value={item.id}>{String(item.name??"Sem nome")} · ID {item.id}</option>)}</select>;if(view==="images")return <form onSubmit={acquire} className="mb-6 flex flex-wrap items-center gap-3 rounded-2xl border border-slate-800 bg-slate-900/50 p-5">{select("area",areas,"Selecione a jazida",area,setArea)}<input required name="start" type="date" defaultValue="2026-09-01" className="field"/><input required name="end" type="date" defaultValue="2026-10-01" className="field"/><label className="text-sm"><input defaultChecked name="SENTINEL-1" type="checkbox" className="mr-1"/>Sentinel-1 (radar)</label><label className="text-sm"><input defaultChecked name="SENTINEL-2" type="checkbox" className="mr-1"/>Sentinel-2 (óptico)</label><button className="rounded-xl bg-amber-400 px-4 font-semibold text-slate-950">Buscar imagens de satélite</button></form>;if(view==="analysis")return <><form onSubmit={analyze} className="mb-2 flex flex-wrap gap-3 rounded-2xl border border-slate-800 bg-slate-900/50 p-5">{select("mine_id",mines,"Selecione a mina")}{select("monitoring_area_id",areas,"Selecione a jazida")}<select required name="analysis_type" defaultValue="CHANGE_DETECTION" className="field"><option value="CHANGE_DETECTION">Detecção de mudanças</option><option value="GOLD_POTENTIAL">Potencial aurífero</option></select>{input("reference_image_id","ID imagem referência")}{input("current_image_id","ID imagem atual")}{input("threshold","Limite","number")}<button className="rounded-xl bg-amber-400 px-4 font-semibold text-slate-950">Enfileirar análise</button></form><p className="mb-6 text-xs text-slate-400">Potencial aurífero usa Sentinel-2 para localizar assinaturas de alteração hidrotermal e óxidos de ferro; o resultado é uma triagem e exige validação geológica e de campo.</p></>;if(view==="reports")return <form onSubmit={report} className="mb-6 flex flex-wrap gap-3 rounded-2xl border border-slate-800 bg-slate-900/50 p-5">{select("mine_id",mines,"Selecione a mina")}<input required name="title" defaultValue="Relatório de monitoramento" className="field"/><select name="type" className="field"><option>MONITORING</option><option>CHANGES</option><option>INSPECTION</option><option>EXECUTIVE</option></select><input required name="period_start" type="date" defaultValue="2026-09-01" className="field"/><input required name="period_end" type="date" defaultValue="2026-10-12" className="field"/><button className="rounded-xl bg-amber-400 px-4 font-semibold text-slate-950">Gerar relatório</button></form>;if(view==="inspections")return <form onSubmit={upload} className="mb-6 flex flex-wrap gap-3 rounded-2xl border border-slate-800 bg-slate-900/50 p-5"><input required value={inspection} onChange={e=>setInspection(e.target.value)} placeholder="ID da inspeção" className="field"/><input required type="file" accept="image/jpeg,image/png,image/webp" onChange={(e:ChangeEvent<HTMLInputElement>)=>setFile(e.target.files?.[0]??null)} className="text-sm"/><button className="rounded-xl bg-amber-400 px-4 font-semibold text-slate-950">Enviar foto</button></form>;return null;}
function Table({rows,cols,loading,target,edit,del,preview,openReport,deletable,mines,areas}:{rows:Row[];cols:string[];loading:boolean;target:string;edit:(r:Row)=>void;del:(r:Row)=>void;preview:(id:number)=>void;openReport:(token:unknown)=>void;deletable:boolean;mines:Row[];areas:Row[]}){const entityName=(id:unknown,entities:Row[])=>{const entity=entities.find(item=>String(item.id)===String(id));return entity?`${String(entity.name??"Sem nome")} · ID ${entity.id}`:val(id);};const pdf=(id:number)=>void apiBlob(`/reports/${id}/pdf`).then(blob=>{const url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download=`relatorio-minevision-${id}.pdf`;link.click();URL.revokeObjectURL(url);});return <div className="app-table"><table><thead><tr>{cols.length?cols.map(c=><th key={c}>{label(c)}</th>):<th>Registros</th>}<th>Ações</th></tr></thead><tbody>{loading?<tr><td className="app-empty" colSpan={Math.max(cols.length,1)+1}>Carregando registros…</td></tr>:rows.length?rows.map(r=><tr key={r.id}>{cols.map(c=><td key={c} className="max-w-52 truncate">{["status","severity","processing_status","role"].includes(c)?<Tag value={r[c]}/>:c==="mine_id"?entityName(r[c],mines):c==="monitoring_area_id"?entityName(r[c],areas):c.endsWith("_at")?when(r[c]):val(r[c])}</td>)}<td className="whitespace-nowrap"><button className="mr-3 text-green-800" onClick={()=>edit(r)}>Editar</button>{target==="satellite-images"&&<button className="mr-3 text-green-800" onClick={()=>preview(r.id)}>Prévia</button>}{target==="reports"&&<><button className="mr-3 text-green-800" onClick={()=>openReport(r.public_token)}>Abrir</button><button className="mr-3 text-green-800" onClick={()=>pdf(r.id)}>PDF</button></>}{target==="alerts"&&<select value={String(r.status)} onChange={e=>void api(`/alerts/${r.id}/status`,{method:"PATCH",body:JSON.stringify({status:e.target.value})}).then(()=>location.reload())} className="field mr-2 text-xs"><option>OPEN</option><option>INVESTIGATING</option><option>RESOLVED</option><option>DISMISSED</option></select>}{deletable&&<button className="text-red-700" onClick={()=>del(r)}>Excluir</button>}</td></tr>):<tr><td className="app-empty" colSpan={Math.max(cols.length,1)+1}>Nenhum registro encontrado. Ajuste a busca ou crie um novo registro.</td></tr>}</tbody></table></div>;}
function Account({me}:{me:Row|null}){return <div className="max-w-2xl"><div className="app-page-intro"><p className="app-kicker">PERFIL E INTEGRAÇÕES</p><h2>Conta e API</h2><p>Dados da sessão e documentação para integrar o MineVision.</p></div><div className="app-panel p-7"><p className="app-kicker">SESSÃO ATUAL</p><p className="mt-3 font-serif text-2xl">{val(me?.name)}</p><p className="mt-1 text-sm text-green-900/70">{val(me?.email)} · <Tag value={me?.role}/></p><div className="mt-7 flex flex-wrap gap-3"><a target="_blank" className="app-button" href="/api/v1/docs">Documentação da API ↗</a><a target="_blank" className="app-button app-button-secondary" href="/api/v1/openapi.json">OpenAPI JSON ↗</a></div></div></div>;}
